/*
 * Boiler Panel v0.1 (DEMO) for Guition JC4880P443C_I_W.
 * LVGL 8.3 / Arduino + ultramcu/guition-jc4880p4-bsp.
 * Portrait 480x800; NO GPIO OUTPUTS; NO remote equipment commands.
 * Cyrillic fonts in boiler_fonts.c are generated by project-specific tooling.
 */
#include <Arduino.h>
#include <stdint.h>
#include <stdio.h>
#include "lvgl.h"
#include "board_p4.h"
#include "lvgl_glue.h"

extern "C" {
  extern const lv_font_t boiler_font_14;
  extern const lv_font_t boiler_font_19;
  extern const lv_font_t boiler_font_25;
  extern const lv_font_t boiler_font_55;
}

static constexpr uint32_t BG = 0x0D1727;
static constexpr uint32_t HEAD = 0x14243A;
static constexpr uint32_t CARD = 0x1B2D44;
static constexpr uint32_t LINE = 0x30465F;
static constexpr uint32_t TXT = 0xF0F6FF;
static constexpr uint32_t MUTED = 0xA7BACF;
static constexpr uint32_t SKY = 0x62CFFF;
static constexpr uint32_t GREEN = 0x6AE7AF;
static constexpr uint32_t ORANGE = 0xFFC57D;
static constexpr uint32_t RED = 0xFFA3AA;

static uint8_t tab = 0; // 0=home, 1=controls, 2=setpoints, 3=diagnostics
static uint8_t mode = 0; // 0=automatic, 1=manual, 2=off
static int temp = 56, low = 50, high = 65;
static bool diesel = false, electric = false, dhw = false, fault = false, prime = false;
static bool dirty = true;

static lv_color_t C(uint32_t hex) { return lv_color_hex(hex); }
static void text_font(lv_obj_t *obj, const lv_font_t *f, uint32_t color) {
  lv_obj_set_style_text_font(obj, f, 0);
  lv_obj_set_style_text_color(obj, C(color), 0);
}
static lv_obj_t *label(lv_obj_t *parent, const char *txt, int x, int y,
                       const lv_font_t *f = &boiler_font_14, uint32_t color = TXT) {
  lv_obj_t *v = lv_label_create(parent);
  lv_label_set_text(v, txt);
  text_font(v, f, color);
  lv_obj_set_pos(v, x, y);
  return v;
}
static lv_obj_t *panel(lv_obj_t *parent, int x, int y, int w, int h, uint32_t fill = CARD) {
  lv_obj_t *v = lv_obj_create(parent);
  lv_obj_set_pos(v, x, y); lv_obj_set_size(v, w, h);
  lv_obj_set_style_bg_opa(v, LV_OPA_COVER, 0);
  lv_obj_set_style_bg_color(v, C(fill), 0);
  lv_obj_set_style_radius(v, 14, 0);
  lv_obj_set_style_border_width(v, 1, 0);
  lv_obj_set_style_border_color(v, C(LINE), 0);
  lv_obj_set_style_pad_all(v, 0, 0);
  lv_obj_clear_flag(v, LV_OBJ_FLAG_SCROLLABLE);
  return v;
}

enum Action : uintptr_t {
  A_HOME=1, A_CONTROL, A_SETTINGS, A_DIAG,
  A_START_DIESEL, A_STOP, A_TOGGLE_ELECTRIC, A_TOGGLE_DHW,
  A_AUTO, A_MANUAL, A_OFF,
  A_LOW_MINUS, A_LOW_PLUS, A_HIGH_MINUS, A_HIGH_PLUS,
  A_TEMP_MINUS, A_TEMP_PLUS, A_FAULT, A_RESET, A_PRIME
};

static void recalc() {
  if (fault || mode == 2) { diesel=false; electric=false; prime=false; return; }
  if (mode == 0) {
    electric = false; prime = false;
    if (temp <= low) diesel=true;
    if (temp >= high) diesel=false;
  }
}

static void on_click(lv_event_t *e) {
  if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
  Action a = (Action)(uintptr_t)lv_event_get_user_data(e);
  switch(a) {
    case A_HOME: tab=0; break;
    case A_CONTROL: tab=1; break;
    case A_SETTINGS: tab=2; break;
    case A_DIAG: tab=3; break;
    case A_START_DIESEL:
      if (!fault) { mode=1; prime=false; electric=false; diesel=true; }
      break;
    case A_STOP: mode=2; diesel=false; electric=false; prime=false; break;
    case A_TOGGLE_ELECTRIC:
      if (!fault) { mode=1; electric=!electric; if(electric) {diesel=false; prime=false;} }
      break;
    case A_TOGGLE_DHW: dhw=!dhw; break;
    case A_AUTO: if(!fault) mode=0; break;
    case A_MANUAL: if(!fault) mode=1; break;
    case A_OFF: mode=2; diesel=false; electric=false; prime=false; break;
    case A_LOW_MINUS: if(low>30) --low; break;
    case A_LOW_PLUS: if(low+5<high) ++low; break;
    case A_HIGH_MINUS: if(high-5>low) --high; break;
    case A_HIGH_PLUS: if(high<90) ++high; break;
    case A_TEMP_MINUS: if(temp>20) --temp; break;
    case A_TEMP_PLUS: if(temp<95) ++temp; break;
    case A_FAULT: fault=true; diesel=false; electric=false; prime=false; mode=2; break;
    case A_RESET: fault=false; prime=false; break;
    case A_PRIME: if(!fault && !diesel && !electric) prime=!prime; break;
    default: break;
  }
  recalc(); dirty=true;  // redraw via timer, never delete clicked widget inside its callback
}

static lv_obj_t *button(lv_obj_t *parent, const char *name, int x, int y,
                        int w, int h, Action a, uint32_t fill=0x264159) {
  lv_obj_t *b = lv_btn_create(parent);
  lv_obj_set_pos(b, x, y); lv_obj_set_size(b, w, h);
  lv_obj_set_style_bg_color(b, C(fill), 0);
  lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(b, 10, 0);
  lv_obj_set_style_border_width(b, 0, 0);
  lv_obj_set_style_shadow_width(b, 0, 0);
  lv_obj_add_event_cb(b, on_click, LV_EVENT_CLICKED, (void *)(uintptr_t)a);
  lv_obj_t *l=lv_label_create(b);
  lv_label_set_text(l, name); text_font(l, &boiler_font_14, TXT); lv_obj_center(l);
  return b;
}
static void label_fmt(lv_obj_t *p, int x, int y, const lv_font_t *font,
                      uint32_t color, const char *fmt, int v) {
  char buf[100]; snprintf(buf,sizeof(buf),fmt,v); label(p,buf,x,y,font,color);
}

static void header(lv_obj_t *scr) {
  lv_obj_t *h=panel(scr,0,0,480,95,HEAD);
  lv_obj_set_style_radius(h,0,0);lv_obj_set_style_border_width(h,0,0);
  label(h,"HOME BOILER CONTROL",20,12,&boiler_font_14,SKY);
  label(h,"КОТЕЛЬНАЯ",20,36,&boiler_font_25,TXT);
  lv_obj_t *tag=panel(h,365,23,96,31,0x355067);
  lv_obj_set_style_border_width(tag,0,0);
  label(tag,"ДЕМО",23,5,&boiler_font_14,ORANGE);
  label(h,"JC4880P443 · v0.1",326,68,&boiler_font_14,MUTED);
}
static void bottom(lv_obj_t *scr) {
  lv_obj_t *bar = panel(scr,0,726,480,74,HEAD);
  lv_obj_set_style_radius(bar,0,0);lv_obj_set_style_border_width(bar,0,0);
  const char *names[4]={"Главная","Управление","Уставки","Сервис"};
  const Action acts[4]={A_HOME,A_CONTROL,A_SETTINGS,A_DIAG};
  for(int i=0;i<4;++i) {
    button(bar,names[i],7+i*119,10,111,52,acts[i],i==tab?0x285E83:0x20354B);
  }
}
static void equipment(lv_obj_t *scr, int x, int y, const char *name,
                      const char *state, bool active) {
  lv_obj_t *c=panel(scr,x,y,216,113);
  label(c,name,13,15,&boiler_font_19,TXT);
  label(c,state,13,62,&boiler_font_14,active?GREEN:MUTED);
}
