static void stepper(lv_obj_t *scr, int y, const char *title,
                    const char *hint, int v, Action minus, Action plus) {
  lv_obj_t *p=panel(scr,15,y,450,114);
  label(p,title,13,10,&boiler_font_19,TXT);
  label(p,hint,13,41,&boiler_font_14,MUTED);
  button(p,"−",15,68,70,37,minus);
  char value[40]; snprintf(value,sizeof(value),"%d°C",v);
  label(p,value,170,67,&boiler_font_25,TXT);
  button(p,"+",365,68,70,37,plus);
}
static void settings(lv_obj_t *scr) {
  label(scr,"Температурные уставки",17,113,&boiler_font_25,TXT);
  label(scr,"Алгоритм проверяется без реальных выходов",17,150,&boiler_font_14,MUTED);
  stepper(scr,184,"Включение нагрева","Нижний порог",low,A_LOW_MINUS,A_LOW_PLUS);
  stepper(scr,313,"Отключение нагрева","Верхний порог",high,A_HIGH_MINUS,A_HIGH_PLUS);
  stepper(scr,442,"Температура · ТЕСТ","Имитация датчика теплоносителя",temp,A_TEMP_MINUS,A_TEMP_PLUS);
  lv_obj_t *p=panel(scr,15,579,450,114,0x1B364B);
  label_fmt(p,15,16,&boiler_font_19,SKY,"Гистерезис: %d°C",high-low);
  label(p,"В режиме АВТО включение при нижнем",15,57,&boiler_font_14,MUTED);
  label(p,"пороге, отключение при верхнем.",15,80,&boiler_font_14,MUTED);
}
static void stat(lv_obj_t *p,int y,const char* title,const char* value) {
  label(p,title,14,y,&boiler_font_14,MUTED);
  label(p,value,245,y,&boiler_font_14,TXT);
}
static void diagnostic(lv_obj_t *scr) {
  label(scr,"Диагностика",17,113,&boiler_font_25,TXT);
  label(scr,"Данные датчиков — симуляция",17,150,&boiler_font_14,MUTED);
  lv_obj_t *p=panel(scr,15,187,450,319);
  label(p,"ESP32-S3: НЕТ СВЯЗИ",14,18,&boiler_font_19,ORANGE);
  stat(p,67,"DS18B20 · GPIO4","22.4°C · ТЕСТ");
  stat(p,109,"NTC · GPIO8","68°C · ТЕСТ");
  stat(p,151,"GL5516 · GPIO19",diesel?"ПЛАМЯ · ТЕСТ":"НЕТ · ТЕСТ");
  stat(p,193,"PM02 VOLT · GPIO5","23.1 В · ТЕСТ");
  stat(p,235,"PM02 CURRENT · GPIO6","0.0 А · ТЕСТ");
  stat(p,277,"Связь RS-485","НЕ НАСТРОЕНА");
  lv_obj_t *s=panel(scr,15,522,450,183);
  label(s,fault?"ТЕСТОВАЯ АВАРИЯ АКТИВНА":"Сервис · тестовые функции",12,13,&boiler_font_19,fault?RED:TXT);
  button(s,"Тест аварии",12,51,205,45,A_FAULT,0x863C4A);
  button(s,"Сброс",232,51,204,45,A_RESET);
  button(s,prime?"Стоп прокачки":"Прокачка · тест",12,111,424,50,A_PRIME,prime?0x863C4A:0x285D77);
}
static void redraw() {
  recalc();
  lv_obj_t *scr=lv_scr_act(); lv_obj_clean(scr);
  lv_obj_set_style_bg_color(scr,C(BG),0);
  lv_obj_set_style_bg_opa(scr,LV_OPA_COVER,0);
  lv_obj_clear_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
  header(scr);
  switch(tab) { case 0: home(scr); break; case 1: control(scr); break;
    case 2: settings(scr); break; default: diagnostic(scr); break; }
  bottom(scr);
}
static void refresh_timer(lv_timer_t *) { if (dirty) {dirty=false; redraw();} }

void setup() {
  Serial.begin(115200);delay(150);
  Serial.println("[BoilerPanel] v0.1 UI ONLY. NO OUTPUTS / NO RS485.");
  if(board_p4_display_init()!=ESP_OK) {
    Serial.println("[BoilerPanel] DISPLAY INIT FAILED");return;
  }
  if(!lvgl_glue_start(true)) {
    Serial.println("[BoilerPanel] LVGL INIT FAILED");return;
  }
  if(lvgl_glue_lock(0)) {
    redraw();dirty=false;
    lv_timer_create(refresh_timer,80,nullptr);
    lvgl_glue_unlock();
  }
  Serial.println("[BoilerPanel] DEMO ready. 480x800 portrait. Touch enabled.");
}
void loop() { delay(500); }
